def gql_execute(src, variables, context)
  doc = nil
  begin
    doc = GQLParser.new(src).parse
  rescue GQLParseError => e
    return gql_parse_error_result(src, e)
  end
  gql_execute_doc(doc, variables, context)
end

# Like graphql-ruby's execute(document: ...): validate and run a parsed document.
def gql_execute_doc(doc, variables, context)
  errors = GQLValidator.new(doc).validate
  return { "errors" => errors } unless errors.empty?
  op = doc.ops[0]
  ex = GQLExecutor.new(doc, context)
  return { "errors" => ex.errors } unless ex.coerce_variables(op, variables)
  data = ex.exec_Query(nil, ex.plan_Query(op.sels))
  ex.errors.empty? ? { "data" => data } : { "errors" => ex.errors, "data" => data }
end
